audio_file = 'demo2.wav'
subtitle_path = 'output.srt'
video_script="""你有没有想过，为什么有些自媒体文案能瞬间引爆网络，而你的却总是默默无闻？今天，我要揭秘的是自媒体文案如何生成爆款的秘密。别急着划走，这个视频可能会改变你的自媒体生涯！首先，我们要明白，爆款文案的核心在于抓住用户的痛点和需求。比如，你写的是美食类内容，那么用户最关心的可能是健康、便捷或是美味。你的文案就要围绕这些点展开，用故事、数据或是情感来打动他们。接下来，我们要学会运用一些心理学技巧。比如，使用数字来增加文案的说服力，‘5分钟做出米其林级甜点’这样的标题，是不是立刻吸引了你的注意？再比如，利用对比和反差，‘他用了这个方法，从零粉丝到百万大V只用了3个月’，这样的故事总能激起人们的好奇心。最后，别忘了在文案中加入行动号召。告诉你的观众，看完视频后他们能做什么，或是如何参与进来。这样不仅能提高用户的参与度，还能让你的内容更具互动性。掌握了这些技巧，相信你的自媒体文案也能成为下一个爆款！"""
subtitle.create(audio_file=audio_file, subtitle_file=subtitle_path)
subtitle.correct(subtitle_file=subtitle_path, video_script=video_script)